class Solution {
public:
    long long findMaximumElegance(vector<vector<int>>& items, int k) {
        sort(items.begin(), items.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[0] > b[0];
        });
        long long total_profit = 0;
        unordered_set<int> seen;
        vector<int> duplicates;
        for (int i = 0; i < k; ++i) {
            int profit = items[i][0], cat = items[i][1];
            total_profit += profit;
            if (seen.count(cat)) duplicates.push_back(profit);
            else seen.insert(cat);
        }
        long long distinct_count = seen.size();
        long long ans = total_profit + distinct_count * distinct_count;
        for (int i = k; i < items.size(); ++i) {
            int profit = items[i][0], cat = items[i][1];
            if (!seen.count(cat) && !duplicates.empty()) {
                seen.insert(cat);
                total_profit += profit - duplicates.back();
                duplicates.pop_back();
                distinct_count++;
                ans = max(ans, total_profit + distinct_count * distinct_count);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long findMaximumElegance(int[][] items, int k) {
        Arrays.sort(items, (a, b) -> Integer.compare(b[0], a[0]));
        long totalProfit = 0;
        Set<Integer> seen = new HashSet<>();
        Deque<Integer> duplicates = new ArrayDeque<>();
        for (int i = 0; i < k; i++) {
            int profit = items[i][0], cat = items[i][1];
            totalProfit += profit;
            if (seen.contains(cat)) duplicates.push(profit);
            else seen.add(cat);
        }
        long distinctCount = seen.size();
        long ans = totalProfit + distinctCount * distinctCount;
        for (int i = k; i < items.length; i++) {
            int profit = items[i][0], cat = items[i][1];
            if (!seen.contains(cat) && !duplicates.isEmpty()) {
                seen.add(cat);
                totalProfit += profit - duplicates.pop();
                distinctCount++;
                ans = Math.max(ans, totalProfit + distinctCount * distinctCount);
            }
        }
        return ans;
    }
}

