var findMaximumElegance = function(items, k) {
    items.sort((a, b) => b[0] - a[0]);
    let totalProfit = 0n;
    const seen = new Set();
    const duplicates = [];
    for (let i = 0; i < k; i++) {
        const [profit, cat] = items[i];
        totalProfit += BigInt(profit);
        if (seen.has(cat)) duplicates.push(BigInt(profit));
        else seen.add(cat);
    }
    let distinctCount = BigInt(seen.size);
    let ans = totalProfit + distinctCount * distinctCount;
    for (let i = k; i < items.length; i++) {
        const [profit, cat] = items[i];
        if (!seen.has(cat) && duplicates.length > 0) {
            seen.add(cat);
            totalProfit += BigInt(profit) - duplicates.pop();
            distinctCount += 1n;
            const candidate = totalProfit + distinctCount * distinctCount;
            if (candidate > ans) ans = candidate;
        }
    }
    return Number(ans);
};
